    23→async function TrendsStatsLoader() {
    24→  const org = await getRequiredCurrentOrg();
    25→  const stats = await getMoodStats({
    26→    userId: org.user.id,
    27→    organizationId: org.id,
    28→    days: 30,
    29→  });
    30→
    31→  return (
    32→    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
    33→      <StatCard
    34→        icon={TrendingUp}
    35→        label="Humeur moyenne"
    36→        value={
    37→          stats.averageMood !== null
    38→            ? stats.averageMood > 0
    39→              ? `+${stats.averageMood.toFixed(1)}`
    40→              : stats.averageMood.toFixed(1)
    41→            : "-"
    42→        }
    43→        variant="primary"
    44→      />
    45→      <StatCard
    46→        icon={Battery}
    47→        label="Énergie moyenne"
    48→        value={stats.averageEnergy?.toFixed(1) ?? "-"}
    49→        unit="/10"
    50→      />
    51→      <StatCard
    52→        icon={Moon}
    53→        label="Sommeil moyen"
    54→        value={stats.averageSleepHours?.toFixed(1) ?? "-"}
    55→        unit="h"
    56→      />
    57→      <StatCard
    58→        icon={Brain}
    59→        label="Anxiété moyenne"
    60→        value={stats.averageAnxiety?.toFixed(1) ?? "-"}
    61→        unit="/10"
    62→      />
    63→    </div>
    64→  );
    65→}
