     1→import { cn } from "@/lib/utils";
     2→import type { ReactNode } from "react";
     3→
     4→export type LayoutProps = {
     5→  /** Content of the layout */
     6→  children: ReactNode;
     7→  /** Max width variant */
     8→  maxWidth?: "sm" | "md" | "lg" | "xl" | "2xl" | "full";
     9→  /** Additional CSS classes */
    10→  className?: string;
    11→};
    12→
    13→/**
    14→ * Layout Component
    15→ *
    16→ * Main container for page content with max-width constraint.
    17→ *
    18→ * @example
    19→ * ```tsx
    20→ * <Layout maxWidth="lg">
    21→ *   <LayoutHeader>
    22→ *     <LayoutTitle>Dashboard</LayoutTitle>
    23→ *   </LayoutHeader>
    24→ *   <LayoutContent>
    25→ *     {children}
    26→ *   </LayoutContent>
    27→ * </Layout>
    28→ * ```
    29→ */
    30→export function Layout({
    31→  children,
    32→  maxWidth = "lg",
    33→  className,
    34→}: LayoutProps) {
    35→  const maxWidthClasses = {
    36→    sm: "max-w-screen-sm",
    37→    md: "max-w-screen-md",
    38→    lg: "max-w-screen-lg",
    39→    xl: "max-w-screen-xl",
    40→    "2xl": "max-w-screen-2xl",
    41→    full: "max-w-full",
    42→  };
    43→
    44→  return (
    45→    <div className={cn("mx-auto w-full px-4 py-6", maxWidthClasses[maxWidth], className)}>
    46→      {children}
    47→    </div>
    48→  );
    49→}
    50→
    51→export type LayoutHeaderProps = {
    52→  /** Content of the header */
    53→  children: ReactNode;
    54→  /** Additional CSS classes */
    55→  className?: string;
    56→};
    57→
    58→/**
    59→ * LayoutHeader Component
    60→ *
    61→ * Header section with flex layout for title and actions.
    62→ */
    63→export function LayoutHeader({ children, className }: LayoutHeaderProps) {
    64→  return (
    65→    <div
    66→      className={cn(
    67→        "mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between",
    68→        className,
    69→      )}
    70→    >
    71→      {children}
    72→    </div>
    73→  );
    74→}
    75→
    76→export type LayoutTitleProps = {
    77→  /** Title text */
    78→  children: ReactNode;
    79→  /** Optional icon */
    80→  icon?: ReactNode;
    81→  /** Description text */
    82→  description?: string;
    83→  /** Additional CSS classes */
    84→  className?: string;
    85→};
    86→
    87→/**
    88→ * LayoutTitle Component
    89→ *
    90→ * Page title with optional icon and description.
    91→ */
    92→export function LayoutTitle({
    93→  children,
    94→  icon,
    95→  description,
    96→  className,
    97→}: LayoutTitleProps) {
    98→  return (
    99→    <div className={cn("flex flex-col gap-1", className)}>
   100→      <h1 className="flex items-center gap-2 text-2xl font-semibold tracking-tight">
   101→        {icon && <span className="text-primary">{icon}</span>}
   102→        {children}
   103→      </h1>
   104→      {description && (
   105→        <p className="text-muted-foreground text-sm">{description}</p>
   106→      )}
   107→    </div>
   108→  );
   109→}
   110→
   111→export type LayoutActionsProps = {
   112→  /** Action buttons/elements */
   113→  children: ReactNode;
   114→  /** Additional CSS classes */
   115→  className?: string;
   116→};
   117→
   118→/**
   119→ * LayoutActions Component
   120→ *
   121→ * Container for header action buttons.
   122→ */
   123→export function LayoutActions({ children, className }: LayoutActionsProps) {
   124→  return (
   125→    <div className={cn("flex items-center gap-2", className)}>{children}</div>
   126→  );
   127→}
   128→
   129→export type LayoutContentProps = {
   130→  /** Content */
   131→  children: ReactNode;
   132→  /** Additional CSS classes */
   133→  className?: string;
   134→};
   135→
   136→/**
   137→ * LayoutContent Component
   138→ *
   139→ * Main content area.
   140→ */
   141→export function LayoutContent({ children, className }: LayoutContentProps) {
   142→  return <div className={cn("space-y-6", className)}>{children}</div>;
   143→}
   144→
   145→export type LayoutSectionProps = {
   146→  /** Section content */
   147→  children: ReactNode;
   148→  /** Section title */
   149→  title?: string;
   150→  /** Section description */
   151→  description?: string;
   152→  /** Additional CSS classes */
   153→  className?: string;
   154→};
   155→
   156→/**
   157→ * LayoutSection Component
   158→ *
   159→ * Section within the layout with optional title.
   160→ */
   161→export function LayoutSection({
   162→  children,
   163→  title,
   164→  description,
   165→  className,
   166→}: LayoutSectionProps) {
   167→  return (
   168→    <section className={cn("space-y-4", className)}>
   169→      {(title || description) && (
   170→        <div className="space-y-1">
   171→          {title && (
   172→            <h2 className="text-lg font-semibold tracking-tight">{title}</h2>
   173→          )}
   174→          {description && (
   175→            <p className="text-muted-foreground text-sm">{description}</p>
   176→          )}
   177→        </div>
   178→      )}
   179→      {children}
   180→    </section>
   181→  );
   182→}
   183→
   184→export type LayoutGridProps = {
   185→  /** Grid items */
   186→  children: ReactNode;
   187→  /** Number of columns */
   188→  cols?: 1 | 2 | 3 | 4;
   189→  /** Additional CSS classes */
   190→  className?: string;
   191→};
   192→
   193→/**
   194→ * LayoutGrid Component
   195→ *
   196→ * Responsive grid layout.
   197→ */
   198→export function LayoutGrid({ children, cols = 2, className }: LayoutGridProps) {
   199→  const colClasses = {
   200→    1: "grid-cols-1",
   201→    2: "grid-cols-1 md:grid-cols-2",
   202→    3: "grid-cols-1 md:grid-cols-2 lg:grid-cols-3",
   203→    4: "grid-cols-1 md:grid-cols-2 lg:grid-cols-4",
   204→  };
   205→
   206→  return (
   207→    <div className={cn("grid gap-4", colClasses[cols], className)}>
   208→      {children}
   209→    </div>
   210→  );
   211→}
