    85→  totalSteps: number;
    86→  /** Current active step (1-indexed) */
    87→  currentStep: number;
    88→  /** Optional labels for each step */
    89→  labels?: string[];
    90→  /** Optional icons for each step (replaces numbers) */
    91→  icons?: LucideIcon[];
    92→  /** Additional CSS classes */
    93→  className?: string;
    94→};
    95→
    96→/**
    97→ * StepIndicator Component
    98→ *
    99→ * Multi-step progress indicator with checkmarks for completed steps.
   100→ * Supports icons instead of numbers when provided.
   101→ * Used in multi-step forms like the daily check-in.
   102→ *
   103→ * @example
   104→ * ```tsx
   105→ * // With numbers
   106→ * <StepIndicator
   107→ *   totalSteps={4}
   108→ *   currentStep={2}
   109→ *   labels={['Humeur', 'Sommeil', 'Médication', 'Contexte']}
   110→ * />
   111→ *
   112→ * // With icons
   113→ * <StepIndicator
   114→ *   totalSteps={4}
   115→ *   currentStep={2}
   116→ *   icons={[Brain, Moon, Pill, MessageSquare]}
   117→ * />
   118→ * ```
   119→ */
   120→export function StepIndicator({
   121→  totalSteps,
   122→  currentStep,
   123→  labels,
   124→  icons,
   125→  className,
   126→}: StepIndicatorProps) {
   127→  return (
   128→    <div className={cn("flex items-center justify-between", className)}>
   129→      {Array.from({ length: totalSteps }, (_, index) => {
   130→        const stepNumber = index + 1;
   131→        const isCompleted = stepNumber < currentStep;
   132→        const isCurrent = stepNumber === currentStep;
   133→        const StepIcon = icons?.[index];
   134→
   135→        return (
   136→          <div key={stepNumber} className="flex flex-1 items-center">
   137→            {/* Step circle */}
   138→            <div className="flex flex-col items-center gap-1">
   139→              <div
   140→                className={cn(
   141→                  "flex size-10 items-center justify-center rounded-full text-sm font-semibold transition-all",
   142→                  isCompleted && "bg-primary text-primary-foreground",
   143→                  isCurrent &&
   144→                    "bg-primary text-primary-foreground ring-primary/20 ring-4",
   145→                  !isCompleted &&
   146→                    !isCurrent &&
   147→                    "bg-border text-muted-foreground",
   148→                )}
   149→              >
   150→                {isCompleted ? (
   151→                  <svg
   152→                    className="size-5"
   153→                    fill="none"
   154→                    viewBox="0 0 24 24"
   155→                    stroke="currentColor"
   156→                    strokeWidth={2}
   157→                  >
   158→                    <path
   159→                      strokeLinecap="round"
   160→                      strokeLinejoin="round"
   161→                      d="M5 13l4 4L19 7"
   162→                    />
   163→                  </svg>
   164→                ) : StepIcon ? (
   165→                  <StepIcon className="size-5" />
   166→                ) : (
   167→                  stepNumber
   168→                )}
   169→              </div>
   170→              {labels?.[index] && (
   171→                <span
   172→                  className={cn(
   173→                    "text-xs",
   174→                    isCurrent
   175→                      ? "text-foreground font-medium"
   176→                      : "text-muted-foreground",
   177→                  )}
   178→                >
   179→                  {labels[index]}
   180→                </span>
   181→              )}
   182→            </div>
   183→
   184→            {/* Connector line */}
   185→            {stepNumber < totalSteps && (
   186→              <div
   187→                className={cn(
   188→                  "mx-2 h-0.5 flex-1",
   189→                  stepNumber < currentStep ? "bg-primary" : "bg-border",
   190→                )}
   191→              />
   192→            )}
   193→          </div>
   194→        );
   195→      })}
   196→    </div>
   197→  );
   198→}
