    47→    mutationFn: async ({ id, isActive }: { id: string; isActive: boolean }) => {
    48→      if (isActive) {
    49→        const result = await deactivateMedicationAction({ id });
    50→        if (result?.serverError) throw new Error(result.serverError);
    51→      } else {
    52→        const result = await reactivateMedicationAction({ id });
    53→        if (result?.serverError) throw new Error(result.serverError);
