     7→
     8→type MoodSliderProps = {
     9→  value: number;
    10→  onChange: (value: number) => void;
    11→  className?: string;
    12→  disabled?: boolean;
    13→};
    14→
    15→/**
    16→ * Get color based on mood value (0-10)
    17→ * Red (0) → Orange (3) → Yellow (5) → Light Green (7) → Green (10)
    18→ */
    19→function getMoodColor(value: number): string {
    20→  if (value <= 2) return "rgb(239, 68, 68)"; // red-500
    21→  if (value <= 4) return "rgb(249, 115, 22)"; // orange-500
    22→  if (value <= 6) return "rgb(234, 179, 8)"; // yellow-500
    23→  if (value <= 8) return "rgb(132, 204, 22)"; // lime-500
    24→  return "rgb(34, 197, 94)"; // green-500
    25→}
    26→
    27→/**
    28→ * Get emoji based on mood value
    29→ */
    30→function getMoodEmoji(value: number): string {
    31→  if (value <= 1) return "😢";
    32→  if (value <= 3) return "😔";
    33→  if (value <= 5) return "😐";
    34→  if (value <= 7) return "🙂";
    35→  if (value <= 9) return "😊";
    36→  return "😄";
    37→}
    38→
    39→/**
    40→ * Trigger haptic feedback if available
    41→ */
    42→function triggerHaptic() {
    43→  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    44→    navigator.vibrate(10);
    45→  }
    46→}
    47→
    48→/**
    49→ * MoodSlider - A slider component for mood tracking (0-10)
    50→ *
    51→ * Features:
    52→ * - Gradient colors based on mood value (red → green)
    53→ * - Large touch target (48px) for accessibility
    54→ * - Haptic feedback on mobile
    55→ * - Emoji indicator
    56→ * - Keyboard accessible (arrow keys)
    57→ */
    58→export function MoodSlider({
    59→  value,
    60→  onChange,
    61→  className,
    62→  disabled = false,
    63→}: MoodSliderProps) {
    64→  const color = getMoodColor(value);
    65→  const emoji = getMoodEmoji(value);
    66→
    67→  const handleValueChange = React.useCallback(
    68→    (values: number[]) => {
    69→      const newValue = values[0];
    70→      if (newValue !== value) {
    71→        triggerHaptic();
    72→        onChange(newValue);
    73→      }
    74→    },
    75→    [value, onChange],
    76→  );
    77→
    78→  return (
    79→    <div className={cn("w-full space-y-4", className)}>
    80→      {/* Value display */}
    81→      <div className="flex items-center justify-center gap-3">
    82→        <span className="text-4xl" role="img" aria-label={`Mood: ${value}/10`}>
    83→          {emoji}
    84→        </span>
    85→        <span
    86→          className="text-4xl font-bold tabular-nums"
    87→          style={{ color }}
    88→          aria-live="polite"
    89→        >
    90→          {value}
    91→        </span>
    92→      </div>
    93→
    94→      {/* Slider */}
    95→      <SliderPrimitive.Root
    96→        value={[value]}
    97→        onValueChange={handleValueChange}
    98→        min={0}
    99→        max={10}
   100→        step={1}
   101→        disabled={disabled}
   102→        className={cn(
   103→          "relative flex w-full touch-none items-center select-none",
   104→          disabled && "cursor-not-allowed opacity-50",
   105→        )}
   106→        aria-label="Mood slider"
   107→      >
   108→        <SliderPrimitive.Track className="relative h-3 w-full grow overflow-hidden rounded-full bg-gray-200 dark:bg-gray-700">
   109→          <SliderPrimitive.Range
   110→            className="absolute h-full transition-colors duration-150"
   111→            style={{ backgroundColor: color }}
   112→          />
   113→        </SliderPrimitive.Track>
   114→        <SliderPrimitive.Thumb
   115→          className={cn(
   116→            "block size-12 rounded-full border-4 shadow-lg transition-all",
   117→            "focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-none",
   118→            "disabled:pointer-events-none",
   119→            "hover:scale-110 active:scale-95",
   120→          )}
   121→          style={{
   122→            backgroundColor: color,
   123→            borderColor: "white",
   124→            boxShadow: `0 4px 14px ${color}40`,
   125→          }}
   126→          aria-label={`Current mood: ${value} out of 10`}
   127→        />
   128→      </SliderPrimitive.Root>
   129→
   130→      {/* Scale labels */}
   131→      <div className="text-muted-foreground flex justify-between px-1 text-xs">
   132→        <span>0</span>
   133→        <span>5</span>
   134→        <span>10</span>
   135→      </div>
   136→    </div>
   137→  );
   138→}
