     6→export type SliderInputProps = {
     7→  /** Label displayed above the slider */
     8→  label: string;
     9→  /** Current value */
    10→  value: number;
    11→  /** Callback when value changes */
    12→  onChange: (value: number) => void;
    13→  /** Minimum value (default: 0) */
    14→  min?: number;
    15→  /** Maximum value (default: 10) */
    16→  max?: number;
    17→  /** Step increment (default: 1) */
    18→  step?: number;
    19→  /** Unit to display after the value (e.g., "h" for hours) */
    20→  unit?: string;
    21→  /** Show min/max labels below the slider */
    22→  showLabels?: { min: string; max: string };
    23→  /** Disabled state */
    24→  disabled?: boolean;
