    30→
    31→/**
    32→ * SliderInput Component
    33→ *
    34→ * A customized slider input with label, value display, and optional min/max labels.
    35→ * Styled to match the MoodTrace design system.
    36→ *
    37→ * @example
    38→ * ```tsx
    39→ * // Energy slider
    40→ * <SliderInput
    41→ *   label="Niveau d'énergie"
    42→ *   value={energy}
    43→ *   onChange={setEnergy}
    44→ *   min={0}
    45→ *   max={10}
    46→ *   showLabels={{ min: "Épuisé", max: "Très énergique" }}
    47→ * />
    48→ *
    49→ * // Sleep hours slider
    50→ * <SliderInput
    51→ *   label="Heures de sommeil"
    52→ *   value={sleepHours}
    53→ *   onChange={setSleepHours}
    54→ *   min={0}
    55→ *   max={14}
    56→ *   unit="h"
    57→ *   showLabels={{ min: "0h", max: "14h" }}
    58→ * />
    59→ * ```
    60→ */
    61→export function SliderInput({
    62→  label,
    63→  value,
    64→  onChange,
    65→  min = 0,
    66→  max = 10,
    67→  step = 1,
    68→  unit = "",
    69→  showLabels,
    70→  disabled = false,
    71→  className,
    72→  id,
    73→}: SliderInputProps) {
    74→  const inputId = id ?? `slider-${label.toLowerCase().replace(/\s+/g, "-")}`;
    75→  const percentage = ((value - min) / (max - min)) * 100;
    76→
    77→  return (
    78→    <div className={cn("flex flex-col gap-2", className)}>
    79→      <div className="flex items-center justify-between">
    80→        <Label htmlFor={inputId} className="text-sm font-medium">
    81→          {label}
    82→        </Label>
    83→        <span className="text-primary text-sm font-semibold">
    84→          {value}
    85→          {unit}
    86→        </span>
    87→      </div>
    88→
    89→      <div className="relative">
    90→        <input
    91→          type="range"
    92→          id={inputId}
    93→          min={min}
    94→          max={max}
    95→          step={step}
    96→          value={value}
    97→          onChange={(e) => onChange(Number(e.target.value))}
    98→          disabled={disabled}
    99→          className={cn(
   100→            "slider-input h-2 w-full cursor-pointer appearance-none rounded-full",
   101→            "bg-muted focus:outline-none",
   102→            "disabled:cursor-not-allowed disabled:opacity-50",
   103→            "[&::-webkit-slider-thumb]:bg-primary [&::-webkit-slider-thumb]:size-5 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:shadow-md [&::-webkit-slider-thumb]:transition-transform [&::-webkit-slider-thumb]:hover:scale-110",
   104→            "[&::-moz-range-thumb]:bg-primary [&::-moz-range-thumb]:size-5 [&::-moz-range-thumb]:appearance-none [&::-moz-range-thumb]:rounded-full [&::-moz-range-thumb]:border-0 [&::-moz-range-thumb]:shadow-md [&::-moz-range-thumb]:transition-transform [&::-moz-range-thumb]:hover:scale-110",
   105→          )}
   106→          style={{
   107→            background: `linear-gradient(to right, var(--primary) 0%, var(--primary) ${percentage}%, var(--muted) ${percentage}%, var(--muted) 100%)`,
   108→          }}
   109→        />
   110→      </div>
   111→
   112→      {showLabels && (
   113→        <div className="flex justify-between">
   114→          <span className="text-muted-foreground text-xs">
   115→            {showLabels.min}
   116→          </span>
   117→          <span className="text-muted-foreground text-xs">
   118→            {showLabels.max}
   119→          </span>
   120→        </div>
   121→      )}
   122→    </div>
   123→  );
   124→}
